"""Read-only Django ORM mappings for Prisma-owned BESTWAY tables.

These models are intentionally unmanaged. Field and table names are explicit so a
future migration cannot silently rely on Django's naming conventions.
"""
from django.contrib.postgres.fields import ArrayField
from django.db import models


class Role(models.TextChoices):
    SUPER_ADMIN = "super_admin"; ADMIN = "admin"; TEACHER = "teacher"; STUDENT = "student"; PARENT = "parent"
class AttendanceState(models.TextChoices): PRESENT = "present"; ABSENT = "absent"; LATE = "late"
class PaymentState(models.TextChoices): PAID = "paid"; UNPAID = "unpaid"; PARTIAL = "partial"
class PaymentMethod(models.TextChoices): MANUAL = "manual"
class TestType(models.TextChoices): IELTS = "ielts"; MULTILEVEL = "multilevel"
class ExamProgram(models.TextChoices): IELTS = "IELTS"; MULTILEVEL = "MULTILEVEL"
class PracticeLevel(models.TextChoices): A1 = "A1"; A2 = "A2"; B1 = "B1"; B2 = "B2"; C1 = "C1"
class TestSection(models.TextChoices): LISTENING = "listening"; READING = "reading"; WRITING = "writing"; SPEAKING = "speaking"
class QuestionType(models.TextChoices): MULTIPLE_CHOICE = "multiple_choice"; SHORT_ANSWER = "short_answer"; ESSAY = "essay"; SPEAKING_PROMPT = "speaking_prompt"
class AttemptStatus(models.TextChoices): IN_PROGRESS = "in_progress"; GRADING = "grading"; COMPLETED = "completed"
class NotificationType(models.TextChoices): POINTS = "points"; PAYMENT_REMINDER = "payment_reminder"; TEST_RESULT = "test_result"; ATTENDANCE = "attendance"; ANNOUNCEMENT = "announcement"; GAME = "game"
class PurchaseStatus(models.TextChoices): PENDING = "pending_confirmation"; PURCHASED = "purchased"
class MockExamType(models.TextChoices): IELTS_ACADEMIC = "ielts_academic"; IELTS_GENERAL = "ielts_general"; MULTILEVEL = "multilevel"
class MockSkill(models.TextChoices): LISTENING = "listening"; READING = "reading"; WRITING = "writing"; SPEAKING = "speaking"
class MockQuestionType(models.TextChoices):
    MULTIPLE_CHOICE = "multiple_choice"; MULTI_SELECT = "multi_select"; TRUE_FALSE_NOTGIVEN = "true_false_notgiven"; YES_NO_NOTGIVEN = "yes_no_notgiven"; MATCHING = "matching"; MATCHING_HEADINGS = "matching_headings"; SENTENCE_COMPLETION = "sentence_completion"; NOTE_COMPLETION = "note_completion"; SUMMARY_COMPLETION = "summary_completion"; TABLE_COMPLETION = "table_completion"; SHORT_ANSWER = "short_answer"; MAP_LABELLING = "map_labelling"; ESSAY_TASK1 = "essay_task1"; ESSAY_TASK2 = "essay_task2"; SPEAKING_TASK = "speaking_task"
