class MockAttemptMode(models.TextChoices): PRACTICE = "practice"; TIMED = "timed"
class AssessmentPolicyMode(models.TextChoices): PRACTICE_AUTO_AI = "PRACTICE_AUTO_AI"; FULL_MOCK_AI_WITH_REVIEW = "FULL_MOCK_AI_WITH_REVIEW"; MANUAL_ONLY = "MANUAL_ONLY"
