class AssessmentScoreSource(models.TextChoices): AI = "AI"; TEACHER = "TEACHER"; ADJUDICATED = "ADJUDICATED"
class AssessmentCallStatus(models.TextChoices): STARTED = "STARTED"; SUCCEEDED = "SUCCEEDED"; FAILED = "FAILED"


class LegacyModel(models.Model):
    class Meta: abstract = True; managed = False


