    id = models.CharField(primary_key=True, max_length=255, db_column="id"); name = models.TextField(db_column="name"); phone = models.TextField(db_column="phone"); email = models.TextField(null=True, db_column="email"); password_hash = models.TextField(db_column="passwordHash"); role = models.CharField(max_length=20, choices=Role.choices, db_column="role"); is_active = models.BooleanField(db_column="isActive"); telegram_chat_id = models.TextField(null=True, db_column="telegramChatId"); created_at = models.DateTimeField(db_column="createdAt"); updated_at = models.DateTimeField(db_column="updatedAt")
